        // The Android app turns these into a real full-screen alarm: a looping ringtone over the
        // lock screen that a repeated notification can never be.
        ...(payloadObj.alarm ? { alarm: "1", taskId: String(payloadObj.taskId || ""), taskText: String(payloadObj.taskText || payloadObj.title || ""), listName: String(payloadObj.listName || ""), user: String(payloadObj.user || ""), tone: String(payloadObj.tone || "") } : {}),
        ...(payloadObj.convKey ? { convKey: String(payloadObj.convKey), msgType: String(payloadObj.msgType || "text"), msgText: String(payloadObj.msgText || ""), msgTs: String(payloadObj.msgTs || Date.now()) } : {}),
