// To-dos are private per user, so the KV key is derived from the signed-in name. Normalised so a
// rename in casing or spacing can't orphan someone's lists.
function todoUserKey(name) {
  return String(name || "").trim().toLowerCase().replace(/[^a-z0-9]+/g, "_") || "unknown";
}
// Fires the push for any task whose reminder time has arrived. Runs every minute, but only touches
// KV for users who actually have a due task - and the push is marked on the task itself, so a
// reminder is never sent twice even if the sweep runs late or twice in the same minute.
async function sweepTodoReminders(env) {
  const idx = (await env.SALES_CACHE.get("todos_users", { type: "json" })) || [];
  const nowMs = Date.now();
  for (const key of idx) {
    const doc = await env.SALES_CACHE.get(`todos_${key}`, { type: "json" });
    if (!doc || !Array.isArray(doc.lists)) continue;
    let changed = false;
    for (const list of doc.lists) {
      for (const task of (list.tasks || [])) {
        if (task.done || task.ackedAt || !task.remindAt) continue;
        const due = new Date(task.remindAt).getTime();
        if (isNaN(due) || due > nowMs) continue;
        // An alarm that arrived hours late is noise, not a reminder.
        if (nowMs - due > 6 * 3600 * 1000) { task.ackedAt = new Date().toISOString(); changed = true; continue; }
        // Keeps ringing rather than notifying once: an unanswered reminder is re-pushed every
        // minute for 20 minutes, which is what makes it an alarm on a phone where the app is shut.
        // It stops the moment the task is ticked or the notification is answered.
        const rings = Number(task.rings) || 0;
        if (rings >= 20) { task.ackedAt = new Date().toISOString(); changed = true; continue; }
        await notifyAllSubscribers(env, {
          title: `⏰ ${task.text || "Reminder"}`,
          body: rings ? "Still waiting · tap to open" : "Tap to open your to-dos",
          tag: `todo-${task.id}`,
          url: "/?screen=todosScreen",
          requireInteraction: true,
          alarm: true,
          taskId: task.id,
          taskText: task.text || "",
          listName: "",
          user: key,
          tone: doc.tone || "bell",
        });
        task.rings = rings + 1;
        task.notifiedAt = new Date().toISOString();
        changed = true;
      }
    }
    if (changed) await env.SALES_CACHE.put(`todos_${key}`, JSON.stringify(doc));
  }
}
async function notifyAllSubscribers(env, payloadObj) {
  try {
    const tag = payloadObj.tag || "";
    const category = tag.startsWith("order-amazon-") || tag.startsWith("order-noon-") ? "amazon_noon_orders"
      : tag.startsWith("return-compensation-") ? "compensations"
      : tag.startsWith("order-") ? "shopify_orders"
      : tag.startsWith("todo-") ? "todos"
      : "messages";
    const catPrefsByDevice = (await env.SALES_CACHE.get("notif_category_prefs_by_device", { type: "json" })) || {};
    const deviceCanReceiveCategory = (deviceKey) => catPrefsByDevice[deviceKey]?.[category] !== false;
    const hrDataForPerms = (await env.SALES_CACHE.get("hr_data", { type: "json" })) || {};
    const rolePerms = hrDataForPerms.permissions || {};
    const catPermKey = { shopify_orders: "Notifications.Shopify Orders", amazon_noon_orders: "Notifications.Amazon / Noon Orders", compensations: "Notifications.Compensations", todos: "Notifications.Reminders", messages: "Notifications.Messages & Returns" }[category];
    const roleCanReceive = (role) => role === "owner" || (rolePerms[role]?.["Notifications"] !== false && rolePerms[role]?.[catPermKey] !== false);
    // Log every push as an in-app notification too (capped list) so the bell icon has a
    // persistent feed/count independent of whether the OS-level push was ever delivered/seen -
    // except Amazon/Noon order alerts, which the user wants pushed to their device but not kept
    // in the in-app notification list (that push send below is unaffected either way).
    if (category !== "amazon_noon_orders") try {
      const log = (await env.SALES_CACHE.get("app_notifications", { type: "json" })) || [];
      // For a given conversation (same tag), keep only ONE entry - update it in place with the
      // latest message instead of stacking a new notification per message from the same customer.
      const tag = payloadObj.tag || "";
      const filtered = tag ? log.filter(n => n.tag !== tag) : log;
      filtered.unshift({ id: crypto.randomUUID(), title: payloadObj.title || "", body: payloadObj.body || "", tag, url: payloadObj.url || "", createdAt: new Date().toISOString(), read: false });
      await env.SALES_CACHE.put("app_notifications", JSON.stringify(filtered.slice(0, 200)));
    } catch (e) { /* logging must never block the actual push */ }

    const subs = (await env.SALES_CACHE.get("push_subscriptions", { type: "json" })) || [];
    const stillValid = [];
    await Promise.all(subs.map(async (sub) => {
      try {
        if (!roleCanReceive(sub.role || "owner") || !deviceCanReceiveCategory(sub.endpoint)) { stillValid.push(sub); return; } // permission/category-blocked, not invalid - keep the subscription
        const res = await sendWebPush(sub, payloadObj);
        if (res.status !== 404 && res.status !== 410) stillValid.push(sub);
      } catch (e) { stillValid.push(sub); /* transient failure - keep the subscription */ }
    }));
    if (stillValid.length !== subs.length) await env.SALES_CACHE.put("push_subscriptions", JSON.stringify(stillValid));

    // Native Android app (Capacitor wrapper) push, via Firebase Cloud Messaging - separate
    // subscriber list since FCM tokens aren't web-push subscriptions.
    if (V.FIREBASE_SERVICE_ACCOUNT_JSON) {
      try {
        const fcmTokens = (await env.SALES_CACHE.get("fcm_tokens", { type: "json" })) || [];
        const stillValidFcm = [];
        await Promise.all(fcmTokens.map(async (t) => {
          const tokenStr = typeof t === "string" ? t : t.token;
          const role = typeof t === "string" ? "owner" : (t.role || "owner");
          try {
            if (!roleCanReceive(role) || !deviceCanReceiveCategory(tokenStr)) { stillValidFcm.push(t); return; } // permission/category-blocked, not invalid - keep the token
            const res = await sendFcmMessage(env, tokenStr, payloadObj);
            if (res.ok || res.status < 400) stillValidFcm.push(t);
            else { const body = await res.text(); if (!body.includes("UNREGISTERED") && !body.includes("NOT_FOUND")) stillValidFcm.push(t); }
          } catch (e) { stillValidFcm.push(t); }
        }));
        if (stillValidFcm.length !== fcmTokens.length) await env.SALES_CACHE.put("fcm_tokens", JSON.stringify(stillValidFcm));
      } catch (e) { /* FCM best-effort too */ }
    }
  } catch (e) { /* notifications are best-effort - never block the caller's real work */ }
}

