  const msgKey = `msg::${key}::${ts}::${Math.random().toString(36).slice(2, 8)}`;
  const msg = { timestamp: ts, ...msgFields };
  if (msg.from === "them" && msg.read === undefined) msg.read = false;
  await env.SALES_CACHE.put(msgKey, JSON.stringify(msg));
  await env.SALES_CACHE.delete("conv_summary_list");
  // Append straight onto the snapshot so an incoming message doesn't cost a full re-read of the
  // conversation on the next open.
