// What an employee's hour is worth, whatever way they are paid. A monthly-salaried employee has no
// hourlyRate, which is why early leaving used to cost them nothing at all - the rate is derived from
// their daily rate (or monthly salary) spread over their own scheduled day instead.
function hrHourlyRateFor(emp) {
  if (!emp) return 0;
  if (emp.hourlyRate > 0) return emp.hourlyRate;
  let scheduledHours = 8;
  if (emp.scheduleStart && emp.scheduleEnd) {
    const [sh, sm] = String(emp.scheduleStart).split(":").map(Number);
    const [eh, em] = String(emp.scheduleEnd).split(":").map(Number);
    let mins = (eh * 60 + em) - (sh * 60 + sm);
    if (mins <= 0) mins += 24 * 60; // overnight shift
    if (mins > 0) scheduledHours = mins / 60;
  }
  const daily = emp.dailyRate > 0 ? emp.dailyRate : (emp.monthlySalary > 0 ? emp.monthlySalary / 22 : 0);
  return daily > 0 ? daily / scheduledHours : 0;
}
// Stamps earlyMinutes/earlyDeduction/earlyLeave onto an attendance record, charging the hours
// between when they left and their scheduled end. Commission-only staff are exempt - there is no
// hourly component of their pay to reduce.
function applyEarlyLeaveDeduction(record, emp, leftAtIso) {
  record.earlyMinutes = 0; record.earlyDeduction = 0; record.earlyLeave = false;
  if (!emp || !emp.scheduleEnd) return record;
  const leftAt = new Date(leftAtIso || record.checkOut || Date.now());
  const cairo = new Date(leftAt.getTime() + 3 * 3600000);
  const [eh, em] = String(emp.scheduleEnd).split(":").map(Number);
  const scheduledEndMinutes = eh * 60 + em;
  const actualEndMinutes = cairo.getUTCHours() * 60 + cairo.getUTCMinutes();
  const earlyMinutes = Math.max(0, scheduledEndMinutes - actualEndMinutes);
  record.earlyMinutes = earlyMinutes;
  record.earlyLeave = earlyMinutes > 0;
  if (earlyMinutes > 0 && !emp.commissionBased) {
    const perHour = hrHourlyRateFor(emp);
    record.earlyDeduction = Math.round((earlyMinutes / 60) * perHour * 100) / 100;
  }
  return record;
}
async function getBostaTicketRules(env) {
  return (await env.SALES_CACHE.get("bosta_ticket_rules", { type: "json" })) || [];
}
// Fires a saved ticket rule against a specific order - resolves its shipment's tracking number,
// fills the rule's reason/description templates ({{tracking_number}}, {{order_number}},
// {{customer_name}}), and calls the real Bosta "create support ticket" API (the same one the
// business.bosta.co Tickets page itself uses - confirmed working via BOSTA_API_KEY auth).
function fillTicketTemplate(template, vars) {
  return (template || "").replace(/\{\{\s*(\w+)\s*\}\}/g, (m, key) => vars[key] ?? "");
}
async function fireBostaTicketRule(env, ruleId, orderGid, extraVars) {
  const rules = await getBostaTicketRules(env);
  const rule = rules.find(r => r.id === ruleId);
  if (!rule) throw new Error("Ticket rule not found");
  const shared = (await env.SALES_CACHE.get("app_shared_data", { type: "json" })) || {};
  const shipment = orderGid ? shared.shipments?.[orderGid] : null;
  const trackingNumber = extraVars?.tracking_number || shipment?.trackingNumber;
  if (!trackingNumber) throw new Error("No Bosta tracking number found for this order");
  const vars = { tracking_number: trackingNumber, order_number: extraVars?.order_number || "", customer_name: extraVars?.customer_name || "" };
  const reason = fillTicketTemplate(rule.reasonTemplate, vars);
  // Bosta's own UI always appends the trackingNumber field's value below the description - so
  // if the description text also spells out the number (from the {{tracking_number}} placeholder),
  // it shows twice. Strip that occurrence from the text we send; the number still appears once,
  // via Bosta's own display of the trackingNumber field.
  const descriptionRaw = fillTicketTemplate(rule.descriptionTemplate || rule.reasonTemplate, vars);
  const stripped = descriptionRaw.split(trackingNumber).join("").replace(/\s{2,}/g, " ").trim();
  // Never send an empty description - keep the original text (number and all) rather than nothing.
  const description = stripped || descriptionRaw.trim() || reason || "Delayed shipment";
  const res = await fetch("https://app.bosta.co/api/v2/tickets/business", {
    method: "POST",
    headers: { Authorization: env.BOSTA_API_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ category: rule.category, subCategory: rule.subCategory, description, reason: (reason || description).slice(0, 200), attachments: [], trackingNumber }),
  });
  const json = await res.json();
  if (!res.ok || json.success === false) {
    const err = new Error(json.message || json.error || `Bosta rejected the ticket (HTTP ${res.status})`);
    err.status = res.status;
    err.detail = json;
    err.sentPayload = { category: rule.category, subCategory: rule.subCategory, trackingNumber };
    throw err;
  }
  return json.data;
}
