async function sendWaFlowMessage(env, phoneDigits, text, imageUrl, orderId) {
  const sendProof = await appsecretProof(META_WA_ACCESS_TOKEN, META_APP_SECRET);
  // When a photo is attached, send it as an image message with the text as its caption instead
  // of a separate text message - that's the only way WhatsApp puts a photo "above" the words in
  // the same bubble (plain "text" messages can't carry media at all).
  const body = imageUrl
    ? { messaging_product: "whatsapp", to: phoneDigits, type: "image", image: { link: imageUrl, caption: text || "" } }
    : { messaging_product: "whatsapp", to: phoneDigits, type: "text", text: { body: text } };
  const res = await fetch(`https://graph.facebook.com/v23.0/${META_WA_PHONE_NUMBER_ID}/messages?access_token=${META_WA_ACCESS_TOKEN}&appsecret_proof=${sendProof}`, {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  const json = await res.json();
  if (res.ok) {
    const msgKey = await appendConv(env, `whatsapp_${phoneDigits}`, "whatsapp", phoneDigits, { from: "us", text, status: "sent", orderId: orderId || undefined }, null);
    if (json.messages?.[0]?.id) await rememberWaMessageId(env, json.messages[0].id, msgKey);
  }
  return { ok: res.ok, json };
}
