          for (let i = 1; i < lines.length; i++) {
            if (!lines[i]) continue;
            const fields = parseCsvLine(lines[i]);
            totalShippedUnits += parseFloat(fields[shippedUnitsIdx] || "0") || 0;
            totalGrossUnits += parseFloat(fields[grossUnitsIdx] || "0") || 0;
            totalCancelledUnits += parseFloat(fields[cancelledUnitsIdx] || "0") || 0;
          }
