          const cookie = await getNoonSessionCookie(env);
          const res = await noonFbnFetch(env, `/_svc/inbound-partners/asn/lines/get_size_classification?length=${q[0]}&width=${q[1]}&height=${q[2]}&weight=${q[3]}`, {}, cookie);
